let data,selected,choices=new Map();const same=(a,b)=>JSON.stringify(a)===JSON.stringify(b),chosen=r=>r.proposedCandidates.find(c=>c.kind===choices.get(r.id))??r.current,warningText=c=>(c.standard?.softWarnings??[]).map(w=>w.rule+': '+(w.message??w.code??'검토')).join('\n')||'SOFT 경고 없음';
let sessionScope,comboEpoch=0,comboKey='',checkedCombination=null,roiReceipt=null,savedDraft=null,flowBusy=false,validationTimer,validationFlight=false;
const selectedChoices=()=>data.regions.map(r=>({id:r.id,kind:choices.get(r.id)??'current'})),requestCommon=revision=>({expectedEditRevision:data.binding.editRevision,expectedContextRevision:data.binding.contextRevision,eventSha256:data.binding.eventSha256,selectedSetSha256:data.binding.selectedSetSha256,expectedLayoutRevision:revision??data.binding.layoutRevision,requestKey:crypto.randomUUID()});
async function roiCall(action,body){const r=await fetch('/api/engine/translation-review-pages/'+data.binding.documentId+'/layout-roi/'+action,{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-Mangohana-Review-Scope':sessionScope},body:JSON.stringify(body)}),v=await r.json();if(!r.ok)throw Error(v.code||v.error||'현재 세션·revision과 검토 자료를 다시 확인해 주세요.');return v;}
function flowControls(){const ready=!!data&&!flowBusy&&!validationFlight;$('validateCombination').disabled=!ready||!!savedDraft;$('roiAck').disabled=!ready||checkedCombination?.status!=='READY_FOR_EXPLICIT_ROI_REVIEW'||!!roiReceipt;$('approveRoi').disabled=$('roiAck').disabled||!$('roiAck').checked;$('saveAck').disabled=!ready||!roiReceipt||!!savedDraft;$('saveExpanded').disabled=$('saveAck').disabled||!$('saveAck').checked;$('layoutAck').disabled=!ready||savedDraft?.state!=='DRAFT';$('approveExpanded').disabled=$('layoutAck').disabled||!$('layoutAck').checked;}
function selectionChanged(){if(!data)return;const key=JSON.stringify(selectedChoices());if(key===comboKey)return;comboKey=key;comboEpoch++;checkedCombination=null;roiReceipt=null;savedDraft=null;for(const id of['roiAck','saveAck','layoutAck'])$(id).checked=false;$('roiStatus').textContent='선택 조합이 바뀌었습니다. 13개 전체를 다시 검사하며 이전 검토 동의는 적용되지 않습니다.';$('roiProof').textContent='';clearTimeout(validationTimer);validationTimer=setTimeout(()=>void validateCombination(),500);flowControls();}
async function validateCombination(){if(!data||flowBusy||savedDraft)return;if(validationFlight){clearTimeout(validationTimer);validationTimer=setTimeout(()=>void validateCombination(),400);return;}const epoch=comboEpoch,selected=selectedChoices();checkedCombination=null;roiReceipt=null;for(const id of['roiAck','saveAck','layoutAck'])$(id).checked=false;validationFlight=true;flowControls();$('roiStatus').textContent='실제 cleaned·원본·마스크와 서명 폰트로 13개 조합을 검사하고 있습니다. 저장·승인·Permit 발급 없음.';try{const result=await roiCall('validate',{...requestCommon(),choices:selected});if(epoch!==comboEpoch)return;checkedCombination=result;const p=result.proposal;$('roiStatus').textContent=result.status+' · HARD '+p.checks.reduce((n,c)=>n+c.standard.hardViolations.length,0)+' · ROI 제안 '+p.expansions.length+'개 · FINAL_RASTER PENDING · 미저장·미승인';$('roiProof').textContent=JSON.stringify({proposalSha256:result.proposalSha256,standardReviewSha256:result.standardReviewSha256,binding:p.binding,source:p.source,cleanedSha256:p.cleanedSha256,expansions:p.expansions,checks:p.checks.map(c=>({order:c.order,id:c.id,font:c.fontSizePx,lines:c.lines,sourceSafe:c.sourceFootprintVerified,cleanedSafe:c.cleanedPixelFootprintVerified,hard:c.standard.hardViolations,soft:c.standard.softWarnings,background:c.background,finalRaster:c.finalRaster})),combinationWarnings:p.combinationWarnings,collisions:p.collisions,executionAuthorized:false},null,2);}catch(e){if(epoch===comboEpoch){checkedCombination=null;$('roiStatus').textContent='BLOCKED · '+e.message+' · 승인하지 마세요.';}}finally{validationFlight=false;flowControls();}}
